"use strict";(globalThis.webpackChunklearnalgorithms=globalThis.webpackChunklearnalgorithms||[]).push([[5719],{5855(e){e.exports=JSON.parse('{"tag":{"label":"Searching","permalink":"/concepts/tags/searching","allTagsPath":"/concepts/tags","count":3,"items":[{"id":"principles-of-algorithmics/searching-case-studies","title":"Case Studies: Searching","description":"Searching is one of the most frequent operations in computing: looking up a user in a database, a word in a dictionary, a file in a directory, a value in a cache. In this final lesson of the chapter we apply everything we have learnt to three classic search algorithms. For each one we count instructions exactly, analyze the best, worst and average cases, express the result with asymptotic notation and connect it with real measurements.","permalink":"/concepts/principles-of-algorithmics/searching-case-studies"},{"id":"principles-of-algorithmics/exercises","title":"Exercises: Principles of Algorithmics","description":"These exercises review the whole chapter, from the definition of an algorithm to searching. They are ordered by lesson, and within each group from easier to harder. Try each one before reading its solution: the solutions are grouped at the end of the page.","permalink":"/concepts/principles-of-algorithmics/exercises"},{"id":"principles-of-algorithmics/proofs","title":"Proofs: Principles of Algorithmics","description":"This page collects the proofs behind the claims of the chapter. The lessons state the results and use them; here they are justified. Each section is self-contained, and the lessons link to the section they need. The proof techniques (induction and loop invariants) are explained in Induction, Correctness and Recurrences.","permalink":"/concepts/principles-of-algorithmics/proofs"}],"unlisted":false}}')}}]);